#!/bin/bash
# Installs, updates, or removes an unpublished Bitcoin Control Center build on
# an Umbrel. Run it on the Umbrel as the umbrel user, from the extracted bundle.
set -euo pipefail

BUNDLE_DIR="$(cd "$(dirname "$0")" && pwd)"
# BUILD_INFO is generated by umbrel/build.sh: APP_ID, VERSION, IMAGE, REGISTRY,
# SOURCE_COMMIT, and ARCHES.
# shellcheck source=/dev/null
source "$BUNDLE_DIR/BUILD_INFO"

UMBREL_ROOT="${UMBREL_ROOT:-$HOME/umbrel}"
REGISTRY_CONTAINER="${APP_ID}-sideload-registry"
REGISTRY_IMAGE="registry:3@sha256:325b4b29b041e82803abeb703e201655e4e23ab83264ec1a7c9ddb0a5b14a6e0"

usage() {
  cat <<EOF
Usage: ./install.sh [command]

Commands:
  install     Install this build, or update an installed copy (default)
  status      Show the installed app state
  logs        Show the app logs
  uninstall   Uninstall the app and DELETE its data

Build: $VERSION ($SOURCE_COMMIT), architectures: $ARCHES
EOF
}

die() {
  echo "Error: $*" >&2
  exit 1
}

# umbrelOS 2.0's CLI reads a root-only token by design, so every call needs sudo.
umbreld_client() {
  sudo umbreld client "$@"
}

app_state() {
  # A query answers within seconds; a stall means umbreld isn't responding.
  timeout 60 sudo umbreld client apps.state.query --appId "$1" ||
    die "Could not read the state of $1 from Umbrel."
}

is_installed() {
  local state
  # Callers use this in conditions, where errexit is off, so exit explicitly.
  state="$(app_state "$1")" || exit 1
  [[ "$state" != *not-installed* ]]
}

store_dir() {
  local dirs=("$UMBREL_ROOT"/app-stores/getumbrel-umbrel-apps-github-*)
  [[ ${#dirs[@]} -eq 1 && -d "${dirs[0]}" ]] ||
    die "Could not find the Umbrel App Store directory under $UMBREL_ROOT/app-stores."
  echo "${dirs[0]}"
}

stop_registry() {
  "${DOCKER[@]}" rm --force "$REGISTRY_CONTAINER" >/dev/null 2>&1 || true
}

wait_for_registry() {
  # Docker accepts connections on the published port before the registry inside
  # is ready, so wait for its API to answer.
  for _ in $(seq 30); do
    if curl --fail --silent --max-time 2 "http://$REGISTRY/v2/" >/dev/null; then
      return 0
    fi
    sleep 1
  done
  die "The temporary registry did not start on $REGISTRY."
}

install_or_update() {
  local arch
  case "$(uname -m)" in
    x86_64) arch=amd64 ;;
    aarch64 | arm64) arch=arm64 ;;
    *) die "Unsupported CPU architecture: $(uname -m)" ;;
  esac
  [[ -f "$BUNDLE_DIR/images/$arch.tar" ]] ||
    die "This bundle has no $arch image. Ask for a build made with: ./umbrel/build.sh --arch $arch"

  for dependency in bitcoin electrs mempool; do
    is_installed "$dependency" || die "Install $dependency from the Umbrel App Store first."
  done

  echo "==> Verifying image checksum..."
  (cd "$BUNDLE_DIR" && grep " images/$arch.tar\$" SHA256SUMS | sha256sum -c)

  echo "==> Loading $arch image..."
  "${DOCKER[@]}" load --input "$BUNDLE_DIR/images/$arch.tar"

  # Umbrel pulls every app image during install and update, so serve this
  # unpublished image from a registry bound to loopback until Umbrel has it.
  echo "==> Starting temporary registry on $REGISTRY..."
  stop_registry
  trap stop_registry EXIT
  "${DOCKER[@]}" run --detach --rm --name "$REGISTRY_CONTAINER" --publish "$REGISTRY:5000" "$REGISTRY_IMAGE" >/dev/null
  wait_for_registry
  "${DOCKER[@]}" push "$IMAGE"
  # Pin what was pushed, so Umbrel installs exactly this image even though the
  # temporary registry accepts pushes from anything on the device.
  local digest
  digest="$("${DOCKER[@]}" inspect --format '{{range .RepoDigests}}{{println .}}{{end}}' "$IMAGE" |
    grep "^${IMAGE%:*}@" | head -1 | cut -d@ -f2 || true)"
  [[ "$digest" == sha256:* ]] || die "Could not read the digest of the pushed image."

  # Umbrel replaces its App Store directory when the store receives new commits,
  # so this copy only needs to last until the install or update below finishes.
  local store
  store="$(store_dir)"
  echo "==> Copying app package to $store/$APP_ID..."
  rsync --archive --delete --exclude .gitkeep "$BUNDLE_DIR/$APP_ID/" "$store/$APP_ID/"
  local compose="$store/$APP_ID/docker-compose.yml"
  sed "s|image: $IMAGE\$|image: $IMAGE@$digest|" "$compose" >"$compose.pinned" && mv "$compose.pinned" "$compose"
  grep -q "image: $IMAGE@$digest" "$compose" || die "Could not pin the image in the app package."

  if is_installed "$APP_ID"; then
    echo "==> Updating $APP_ID to $VERSION..."
    umbreld_client apps.update.mutate --appId "$APP_ID"
  else
    echo "==> Installing $APP_ID $VERSION..."
    umbreld_client apps.install.mutate --appId "$APP_ID"
  fi

  app_state "$APP_ID"
  echo ""
  echo "Open Bitcoin Control Center from the Umbrel home screen to use its HTTPS launch."
  echo "Logs: $BUNDLE_DIR/install.sh logs    Remove: $BUNDLE_DIR/install.sh uninstall"
}

uninstall() {
  echo "Uninstalling $APP_ID deletes its accounts, history, and settings from this Umbrel."
  read -r -p "Type $APP_ID to continue: " confirmation
  [[ "$confirmation" == "$APP_ID" ]] || die "Cancelled."

  umbreld_client apps.uninstall.mutate --appId "$APP_ID"
  rm -rf "$(store_dir)/$APP_ID"
  "${DOCKER[@]}" image rm "$IMAGE" >/dev/null 2>&1 || true
  echo "Uninstalled $APP_ID."
}

[[ $EUID -ne 0 ]] || die "Run this as the umbrel user, not root, so Umbrel can read the copied app files."
command -v umbreld >/dev/null ||
  die "umbreld was not found. Run this on the Umbrel: Settings → Advanced settings → Terminal → umbrelOS."

case "${1:-install}" in
  install | status | logs | uninstall)
    # Ask once up front; sudo remembers the password for the rest of the run.
    echo "This installer uses administrator access for Umbrel's app commands. If asked, enter your Umbrel password."
    sudo -v || die "Administrator access is required."
    ;;
esac

if docker info >/dev/null 2>&1; then
  DOCKER=(docker)
else
  DOCKER=(sudo docker)
fi

case "${1:-install}" in
  install) install_or_update ;;
  status)
    echo "Bundle: $VERSION ($SOURCE_COMMIT)"
    app_state "$APP_ID"
    ;;
  logs) umbreld_client apps.logs.query --appId "$APP_ID" ;;
  uninstall) uninstall ;;
  --help | -h | help) usage ;;
  *)
    usage
    exit 1
    ;;
esac
